package view;
import model.*;
public final class MenuView {private MenuView(){}public static void titulo(){System.out.println(Cores.CIANO+"========================================\n             DELTA TRIGGER\n                AETHORIA\n========================================"+Cores.RESET);}public static int menuInicial(boolean save){titulo();System.out.println("\n1 - Novo Jogo");System.out.println("2 - Carregar Jogo"+(save?"":" (nenhum save encontrado)"));System.out.println("3 - Sair");return Entrada.lerInt("Escolha: ");}public static int escolherLider(){while(true){System.out.println("\n========================================\n           ESCOLHA O LIDER\n========================================");System.out.println(Cores.kael("1 - Kael | Guerreiro | linha de frente"));System.out.println(Cores.lyra("2 - Lyra | Suporte | cura e apoio"));System.out.println("0 - Voltar");int op=Entrada.lerInt("Escolha: ");if(op==1||op==2)return op;if(op==0)return 0;System.out.println(Cores.aviso("Opcao invalida. Escolha 1, 2 ou 0."));}}}
